import json,sys,random
sys.path.insert(0,'/workspace/t'); sys.path.insert(0,'/workspace')
from wire import v,envelope
from diff import cmp

def V(x,r):
    w=r.choice([None,None,None,2,4,8])
    if w is None: return v(x)
    return v(x,w) if x<2**(8*w-2) else v(x)

SIDS=[0,1,2,3,4,8,12,16,20,24,5,9,13,17]

def rnd_frame(r):
    t=r.choice([0x01,0x02,0x03,0x06,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,0x10,0x11,0x14,0x15,0x1a,0x1b,0x1c,0x1d,0x30,0x31,0x18,0x19,0x04,0x05,0x12,0x13,0x16,0x17])
    if 0x08<=t<=0x0f:
        out=bytes([t])+V(r.choice(SIDS),r)
        if t&4: out+=V(r.choice([0,0,1,3,5]),r)
        data=bytes(r.randrange(256) for _ in range(r.choice([0,1,2,3])))
        if t&2: out+=V(len(data),r)
        return out+data
    if t in (0x02,0x03):
        largest=r.choice([0,3,10,50]); first=r.choice([0,0,1,largest])
        low=largest-first; pairs=[]
        for _ in range(r.choice([0,1,2])):
            gap=r.choice([0,1,3]); rng=r.choice([0,1,2])
            if low>=gap+2 and rng<=low-gap-2:
                pairs.append((gap,rng)); low=low-gap-2-rng
            else: break
        out=bytes([t])+V(largest,r)+V(0,r)+V(len(pairs),r)+V(first,r)
        for g,x in pairs: out+=V(g,r)+V(x,r)
        if t==0x03: out+=V(1,r)+V(2,r)+V(3,r)
        return out
    if t==0x06: return bytes([t])+V(r.choice([0,0,1,4]),r)+V(r.choice([0,1,2]),r)+bytes(r.randrange(256) for _ in range(r.choice([0,1,2])))
    if t==0x04: return bytes([t])+V(r.choice(SIDS),r)+V(r.choice([0,11]),r)+V(r.choice([0,1,3,5,7,20]),r)
    if t==0x05: return bytes([t])+V(r.choice(SIDS),r)+V(r.choice([0,13]),r)
    if t in (0x11,0x15): return bytes([t])+V(r.choice(SIDS),r)+V(r.choice([0,1,10]),r)
    if t==0x18: return bytes([t])+V(r.choice([0,1,2]),r)+V(r.choice([0,0,1,2]),r)+bytes([r.choice([1,2,3])])+bytes([r.randrange(4)+1])+bytes(16)
    if t==0x19: return bytes([t])+V(r.choice([0,1,2,3]),r)
    if t in (0x1a,0x1b): return bytes([t])+bytes(r.randrange(256) for _ in range(8))
    if t==0x1c: return bytes([t])+V(r.randrange(5),r)+V(r.choice([0,1]),r)+V(r.choice([0,2]),r)+b're'
    if t==0x1d: return bytes([t])+V(r.randrange(5),r)+V(r.choice([0,2]),r)+b're'
    if t==0x30: return bytes([t])+bytes(r.randrange(256) for _ in range(r.randrange(0,4)))
    if t==0x31: return bytes([t])+V(r.choice([0,1,4]),r)+b'ab'
    if t in (0x10,0x12,0x13,0x14,0x16,0x17): return bytes([t])+V(r.choice([0,3,7,2**60]),r)
    return bytes([t])

def env(r,lvl,pn,frames,cid,phase,width):
    if lvl=='A':
        return bytes([0x40|(phase<<2)|(width-1)])+cid+ (pn%(2**(8*width))).to_bytes(width,'big')+frames
    head=bytes([(0xc0 if lvl=='I' else 0xe0)|(width-1)])+b'\0\0\0\1'+bytes([len(cid)])+cid+bytes([1])+b'\xbb'
    if lvl=='I':
        tok=b'' if r.random()<0.5 else b'12'
        head+=V(len(tok),r)+tok
    body=(width+len(frames)).to_bytes(8,'big') if r.random()<0.3 else v(width+len(frames))
    return head+body+(pn%(2**(8*width))).to_bytes(width,'big')+frames

def gen(r):
    nc=r.choice([1,2,3])
    cids=[bytes([0xaa]),bytes([0xbb]),bytes([0xcc])][:nc]
    lim=dict(connection=r.choice([3,10,40,2**62-1]),stream=r.choice([3,10,40,2**62-1]),
             bidi=r.choice([1,2,4,8]),uni=r.choice([1,2,4,8]),cids=r.choice([2,3,4]))
    loc=dict(bidi=r.choice([1,2,3]),uni=r.choice([1,2,3]),cids=[c.hex() for c in cids])
    peer=dict(cid='cc',token='00'*16)
    seeds=dict(I=r.choice([None,None,0,5]),H=r.choice([None,None,0,3]),A=r.choice([None,None,0,4,7]))
    events=[]; pn={'I':0,'H':0,'A':0}
    for _ in range(r.randrange(0,9)):
        if r.random()<0.2:
            events.append({'keys':r.sample(['I','H','A'],r.randrange(0,4))}); continue
        wire=b''; auth=[]
        for _ in range(r.randrange(1,4)):
            lvl=r.choice(['I','H','A','A'])
            frames=b''.join(rnd_frame(r) for _ in range(r.randrange(0,5)))
            width=r.choice([1,1,1,2,4])
            pn[lvl]+=r.choice([0,1,1,2,7])
            ann=r.choice([None,0,0,0,1,1,2])
            phase=r.choice([0,1])
            if ann is not None and r.random()<0.7: phase=ann&1
            cid=r.choice(cids) if lvl=='A' else bytes([r.randrange(3)])
            wire+=env(r,lvl,pn[lvl],frames,cid,phase,width)
            auth.append(ann)
        events.append({'datagram':{'wire':wire.hex(),'auth':auth}})
    return dict(limits=lim,local=loc,peer=peer,received=seeds,events=events)

r=random.Random(int(sys.argv[1])); N=int(sys.argv[2]); bad=0
for i in range(N):
    tr=gen(r)
    if not cmp({'traces':[tr]},'seed%d case%d'%(int(sys.argv[1]),i)): bad+=1
    if bad>2: break
print('done bad=',bad)
